using System.Collections.Generic;

namespace Hardlight
{
	// Original HLAutoGenerated 0x0200001d (TypeDefIndex 8497); original spelling retained.
	// The .cctor 0x060000b2 @0x19E6200 fills each table in native Add order.
	// GetString looks the value up in the live table; a miss is formatted with
	// String.Format("0x{0:X}") on the boxed value and cached through set_Item.
	public static class HardlightEnumExtentions
	{
		private static Dictionary<DynamicPageEntry, string> DynamicPageEntryEnumToString =
			new Dictionary<DynamicPageEntry, string>(HardlightEnumComparers.DynamicPageEntryComparer)
			{
				{ DynamicPageEntry.None, "None" }
			};

		private static Dictionary<HLAudioTypes, string> HLAudioTypesEnumToString =
			new Dictionary<HLAudioTypes, string>(HardlightEnumComparers.HLAudioTypesComparer)
			{
				{ HLAudioTypes.None, "None" }
			};

		// 0x060000b0 @0x19E5FB0
		public static string GetString(this DynamicPageEntry value)
		{
			string result;
			if (!DynamicPageEntryEnumToString.TryGetValue(value, out result))
			{
				result = string.Format("0x{0:X}", value);
				DynamicPageEntryEnumToString[value] = result;
			}
			return result;
		}

		// 0x060000b1 @0x19E60D0
		public static string GetString(this HLAudioTypes value)
		{
			string result;
			if (!HLAudioTypesEnumToString.TryGetValue(value, out result))
			{
				result = string.Format("0x{0:X}", value);
				HLAudioTypesEnumToString[value] = result;
			}
			return result;
		}
	}
}
